import{_ as d,C as a,o,c as r,E as i,a2 as n}from"./chunks/framework.Cm6XCzck.js";const m=JSON.parse('{"title":"TMPA–FCoP–CodeFlowMu 实施案例 — 正式版 I1.0","description":"","frontmatter":{"title":"TMPA–FCoP–CodeFlowMu 实施案例 — 正式版 I1.0","type":"implementation-case","domain":"TMPA","version":"I1.0","status":"stable-release","source":"github-main","related":["TMPA Architecture Paper","TMPA Core Specification","FCoP","CodeFlowMu"],"outline":"deep"},"headers":[],"relativePath":"zh/publications/implementation-case-i1.0.md","filePath":"zh/publications/implementation-case-i1.0.md","lastUpdated":1786439037000}'),l={name:"zh/publications/implementation-case-i1.0.md"};function s(c,t,h,p,u,g){const e=a("ArticleCover");return o(),r("div",null,[i(e,{image:"/assets/covers/implementation-case.svg",kicker:"工程案例",title:"TMPA 实施案例",summary:"CodeFlowMu V1.8.0 针对 TMPA Core S1.0 精确输入的产品运行与锁定公开证据包。",version:"I1.0",status:"正式发布版 · S1.0 产品证据 · 14/14 PASS",languageHref:"/en/publications/implementation-case-i1.0",languageLabel:"English"}),t[0]||(t[0]=n(`<h1 id="tmpa-实施与案例报告" tabindex="-1">TMPA 实施与案例报告 <a class="header-anchor" href="#tmpa-实施与案例报告" aria-label="Permalink to &quot;TMPA 实施与案例报告&quot;">​</a></h1><h2 id="tmpa-core-s1-0、fcop、codeflowmu-v1-8-0-与保留的现场证据" tabindex="-1">TMPA Core S1.0、FCoP、CodeFlowMu V1.8.0 与保留的现场证据 <a class="header-anchor" href="#tmpa-core-s1-0、fcop、codeflowmu-v1-8-0-与保留的现场证据" aria-label="Permalink to &quot;TMPA Core S1.0、FCoP、CodeFlowMu V1.8.0 与保留的现场证据&quot;">​</a></h2><blockquote><p><strong>文档版本：</strong> I1.0<br><strong>状态：</strong> 正式实施与案例报告<br><strong>规范目标：</strong> <a href="/joinwell52/zh/publications/tmpa-core-specification-s1.0">TMPA Core Specification S1.0</a>，冻结候选 Commit <code>942cbb097eb3d662662f96a2269818ec9d7ca2ed</code><br><strong>受测产品：</strong> CodeFlowMu V1.8.0，证据 Commit <code>c1e1f724293e8048fc3a956b6f6df8cf83f54830</code><br><strong>证据采集：</strong> 2026-08-11，Asia/Shanghai<br><strong>正式证据包：</strong> <code>tmpa-i1.0-codeflowmu-v1.8.0-s1.0-evidence-20260811.zip</code><br><strong>压缩包 SHA-256：</strong> <code>9b92b06c3e46c8019362f55075be4ed066cb7a9c0d9859945b6c3b7de8840d04</code></p></blockquote><h2 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to &quot;摘要&quot;">​</a></h2><p>I1.0 使用规范候选 Commit 冻结的精确字节，对 CodeFlowMu V1.8.0 执行 TMPA Core S1.0 全部十四项强制准则。CodeFlowMu 产品路径报告 <strong>14 PASS、0 PARTIAL、0 NOT RUN、0 FAIL</strong>。Runner 调用 <code>GovernanceReader.readSync</code>，不调用 TMPA Reference Reader。输入 Bundle Digest 为 <code>sha256:f98764987760cdc8ac356b1265fc98485f33345e7d6ffc8575ccb059ddd34daa</code>，结果 Digest 为 <code>sha256:0f0f642449db1853371861751a7a8ea36dce00013f53e32012a5e4dae45f4c39</code>。</p><p>证据包固定了 S1.0 Schema、Profile、Fixture、产品 Adapter 与 Reader 源码、CodeFlowMu 与 FCoP 修订、依赖锁、原始命令日志、修复前失败、最终回归结果、精简干净环境复现器，以及覆盖 889 个文件的 SHA-256 Manifest。最终回归记录包括 TMPA Runtime 24/24、Runtime 1,522 passed / 0 failed / 1 skipped、Shell 791/791，以及 FCoP 参考实现 1,210 passed / 2 skipped。</p><p>证据支持的最强结论是：<strong>一个精确实现针对一个精确 S1.0 Bundle，由作者运行并 demonstrated 的产品行为</strong>。它不是独立验证、第三方认证、普遍一致性、TMPA 理论证明、语义真值证明、幻觉消除证明或独立采用。</p><h1 id="_1-范围与研究问题" tabindex="-1">1. 范围与研究问题 <a class="header-anchor" href="#_1-范围与研究问题" aria-label="Permalink to &quot;1. 范围与研究问题&quot;">​</a></h1><p>I1.0 回答：</p><ol><li>CodeFlowMu V1.8.0 产品 Reader 是否针对冻结的精确输入 Bundle 满足 S1.0 C01–C14？</li><li>在不以 Reference Reader 替代产品路径的前提下，规范修订、产品修订、输入 Bundle、逐项结果、回归运行与证据归档能否被追踪？</li><li>证据包是否保留修复前结果，并在不削弱 S1.0 准则的前提下演示干净环境复现器？</li><li>哪些发现达到 demonstrated，哪些结论仍无证据支持？</li></ol><p>裁决单位是固定 Bundle 上绑定具体准则的主张。证据成熟度与符合性裁决分开报告：</p><table tabindex="0"><thead><tr><th>证据层级</th><th>I1.0 中的含义</th><th style="text-align:right;">是否达到</th></tr></thead><tbody><tr><td>Specified</td><td>S1.0 条款、Schema、Profile 与 C01–C14 定义所需行为</td><td style="text-align:right;">是</td></tr><tr><td>Implemented</td><td>CodeFlowMu V1.8.0 包含相应 Adapter、Reader、协议与治理机制</td><td style="text-align:right;">是</td></tr><tr><td>Demonstrated</td><td>作者运行的产品与回归执行产生可检查证据</td><td style="text-align:right;">是，仅限固定 Bundle 与修订</td></tr><tr><td>Independently Adopted</td><td>无关联组织采用并独立验证该机制</td><td style="text-align:right;">否</td></tr></tbody></table><h1 id="_2-架构与证据边界" tabindex="-1">2. 架构与证据边界 <a class="header-anchor" href="#_2-架构与证据边界" aria-label="Permalink to &quot;2. 架构与证据边界&quot;">​</a></h1><p>当前指导与实现关系为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TMPA Architecture Paper A1.0</span></span>
<span class="line"><span>        ↓ 提供架构理论与设计方向</span></span>
<span class="line"><span>TMPA Core Specification S1.0</span></span>
<span class="line"><span>        ↓ 固定规范对象、Reader 与符合性行为</span></span>
<span class="line"><span>FCoP 协议</span></span>
<span class="line"><span>        ↓ 提供文件型协作与证据 Profile</span></span>
<span class="line"><span>CodeFlowMu V1.8.0</span></span>
<span class="line"><span>        ↓ 实现并消费 Adapter/Reader 结果</span></span>
<span class="line"><span>有限案例、治理门禁、恢复与审计视图</span></span></code></pre></div><p>TMPA 是理论与规范治理层。FCoP 是可复用协作协议，不是应用程序；<code>fcop</code> 和 <code>fcop-mcp</code> Package 是 FCoP 的参考实现，不等于协议本身。CodeFlowMu 是受 TMPA 指导的工程系统：产生并消费协作证据，把 FCoP 工件投影为 TMPA 候选对象，重建治理视图，并让 Workflow、Review、Recovery 与 Audit 组件消费结果。</p><p>历史共同演化另行表述。小典 AI、FCoP、CodeFlowMu 与 TMPA 具有作者控制的工程谱系，工程反馈帮助完善当前形式化；这种谱系不会使实现成为理论证明。WP-13 仍是角色分离证据准入与事实核查的有限案例；它不证明幻觉消除，也不替代 S1.0 C01–C14 运行。</p><h1 id="_3-固定来源与证据设计" tabindex="-1">3. 固定来源与证据设计 <a class="header-anchor" href="#_3-固定来源与证据设计" aria-label="Permalink to &quot;3. 固定来源与证据设计&quot;">​</a></h1><h2 id="_3-1-锁定身份" tabindex="-1">3.1 锁定身份 <a class="header-anchor" href="#_3-1-锁定身份" aria-label="Permalink to &quot;3.1 锁定身份&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>固定身份</th><th>本报告中的角色</th></tr></thead><tbody><tr><td>TMPA Core</td><td>S1.0 候选 Commit <code>942cbb097eb3d662662f96a2269818ec9d7ca2ed</code></td><td>规范输入</td></tr><tr><td>CodeFlowMu</td><td>V1.8.0 证据 Commit <code>c1e1f724293e8048fc3a956b6f6df8cf83f54830</code></td><td>受测产品</td></tr><tr><td>CodeFlowMu Protocol Surface</td><td>V1.2.0</td><td>产品 Schema 与 Validator 表面</td></tr><tr><td>FCoP 参考实现</td><td>Commit <code>da79dfefd99f597c9e422ce9edec22157f915a21</code></td><td>仅作为锁定依赖回归</td></tr><tr><td>产品 Reader</td><td><code>GovernanceReader.readSync</code></td><td>必须执行的路径</td></tr><tr><td>产品 Adapter</td><td><code>FcopSourceAdapter.projectFcopToTmpa</code></td><td>FCoP 到 TMPA 的投影路径</td></tr></tbody></table><p>产品运行使用隔离且 tracked-clean 的证据 Worktree。原 CodeFlowMu 母体 Worktree 被观察为 dirty 且持续变化，因此不作为证据执行根。V1.8.0 证据 Commit 在采集时仅存在于本地，尚未 Push、Tag 或 Release。证据归档因此包含完整源码快照与 V1.7.0→V1.8.0 Patch。这支持检查受测源码，但不会把该 Commit 自动变成 CodeFlowMu 公共 Release。</p><h2 id="_3-2-固定机器输入" tabindex="-1">3.2 固定机器输入 <a class="header-anchor" href="#_3-2-固定机器输入" aria-label="Permalink to &quot;3.2 固定机器输入&quot;">​</a></h2><p>运行锁定四份 S1.0 JSON Schema、Lifecycle Profile、Canonicalization Profile、Fixture 与输入 Bundle 身份。四份已发布 Schema 的 Hash 为：</p><table tabindex="0"><thead><tr><th>Schema</th><th>SHA-256</th></tr></thead><tbody><tr><td>Governance object</td><td><code>a2829cd7149c3054a52886365f2293a23106b636b0c52799739bfabdab1ff4fa</code></td></tr><tr><td>Lifecycle Profile</td><td><code>481a61ac2485bbaf15d90e9c5a255ad9ce6a55971190f0fe404856be4b10f993</code></td></tr><tr><td>Reader result</td><td><code>4527df7096fe840b85b245e50d5cea576ff359d50a54d17c8873a7b4f458d431</code></td></tr><tr><td>Conformance result</td><td><code>4b1ecebf83e62d2aa1aff0e79a0cd0ea0a85fbc14a426d5fe873ab40aefdc2fe</code></td></tr></tbody></table><h2 id="_3-3-证据构造" tabindex="-1">3.3 证据构造 <a class="header-anchor" href="#_3-3-证据构造" aria-label="Permalink to &quot;3.3 证据构造&quot;">​</a></h2><p>对每项准则，产品 Runner 记录 Manifest、显式强制断言、产品输入调用、Canonical Reader 输出、断言结果、Manifest Digest 与 Result Digest。聚合结果按照 S1.0 conformance-result Schema 验证。原始 stdout、stderr、Exit Status、Command、Working Directory、Environment、Dependency-lock Digest 与修复历史均被保留。</p><p>冻结的 S1.0 候选语料库仍包含历史产品 <code>NOT RUN</code> 基线。I1.0 不改写它，而是把 V1.8.0 产品结果登记为后续外部精确版本运行，使候选历史与后续证据保持可区分。</p><h1 id="_4-已执行测试基线" tabindex="-1">4. 已执行测试基线 <a class="header-anchor" href="#_4-已执行测试基线" aria-label="Permalink to &quot;4. 已执行测试基线&quot;">​</a></h1><p>正式产品命令为 <code>npm run test:tmpa:s1.0</code>。它针对固定 Bundle 执行 CodeFlowMu 产品 Reader，并产生：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TMPA Core: S1.0</span></span>
<span class="line"><span>Implementation: CodeFlowMu V1.8.0</span></span>
<span class="line"><span>Product Reader called: true</span></span>
<span class="line"><span>Reference Reader called: false</span></span>
<span class="line"><span>PASS: 14</span></span>
<span class="line"><span>PARTIAL: 0</span></span>
<span class="line"><span>NOT RUN: 0</span></span>
<span class="line"><span>FAIL: 0</span></span>
<span class="line"><span>Aggregate: PASS</span></span></code></pre></div><p>S1.0 Reference Reader 单独报告 14/14 PASS。该结果验证作者维护的参考路径，不计为 CodeFlowMu 产品结果。</p><h1 id="_5-c01–c14-产品结果" tabindex="-1">5. C01–C14 产品结果 <a class="header-anchor" href="#_5-c01–c14-产品结果" aria-label="Permalink to &quot;5. C01–C14 产品结果&quot;">​</a></h1><table tabindex="0"><thead><tr><th>准则</th><th>受测行为</th><th style="text-align:right;">强制断言数</th><th style="text-align:right;">结果</th></tr></thead><tbody><tr><td>C01</td><td>Schema 验证与无效形状拒绝</td><td style="text-align:right;">3</td><td style="text-align:right;">PASS</td></tr><tr><td>C02</td><td>主载体与单写者不可变性</td><td style="text-align:right;">5</td><td style="text-align:right;">PASS</td></tr><tr><td>C03</td><td>带来源 Provenance 的重复身份处理</td><td style="text-align:right;">5</td><td style="text-align:right;">PASS</td></tr><tr><td>C04</td><td>单流连续性与异步推进</td><td style="text-align:right;">4</td><td style="text-align:right;">PASS</td></tr><tr><td>C05</td><td>角色权限判断</td><td style="text-align:right;">5</td><td style="text-align:right;">PASS</td></tr><tr><td>C06</td><td>生命周期合法性与状态保留</td><td style="text-align:right;">9</td><td style="text-align:right;">PASS</td></tr><tr><td>C07</td><td>职责分离与人工批准授权</td><td style="text-align:right;">10</td><td style="text-align:right;">PASS</td></tr><tr><td>C08</td><td>完整性篡改检测</td><td style="text-align:right;">3</td><td style="text-align:right;">PASS</td></tr><tr><td>C09</td><td>缺失引用处理</td><td style="text-align:right;">4</td><td style="text-align:right;">PASS</td></tr><tr><td>C10</td><td>禁止循环检测</td><td style="text-align:right;">4</td><td style="text-align:right;">PASS</td></tr><tr><td>C11</td><td>聚合与重建确定性</td><td style="text-align:right;">4</td><td style="text-align:right;">PASS</td></tr><tr><td>C12</td><td>冲突保留与显式解决</td><td style="text-align:right;">5</td><td style="text-align:right;">PASS</td></tr><tr><td>C13</td><td>恢复行为</td><td style="text-align:right;">5</td><td style="text-align:right;">PASS</td></tr><tr><td>C14</td><td>终态历史保留</td><td style="text-align:right;">5</td><td style="text-align:right;">PASS</td></tr></tbody></table><p>出版审查重新计算了 71 项断言。全部 Manifest Digest、Actual-result Digest、输入 Bundle Digest 与聚合 conformance-result Digest 均与证据包记录一致。</p><h1 id="_6-s0-6-到-s1-0-工程增量" tabindex="-1">6. S0.6 到 S1.0 工程增量 <a class="header-anchor" href="#_6-s0-6-到-s1-0-工程增量" aria-label="Permalink to &quot;6. S0.6 到 S1.0 工程增量&quot;">​</a></h1><h2 id="_6-1-稳定机器身份" tabindex="-1">6.1 稳定机器身份 <a class="header-anchor" href="#_6-1-稳定机器身份" aria-label="Permalink to &quot;6.1 稳定机器身份&quot;">​</a></h2><p>S1.0 以稳定的 Schema ID、Profile Identity、Canonicalization Identity 与可执行语料路径，正式发布已经审查的 S0.6 行为。CodeFlowMu V1.8.0 把 Validator 与 Reader 绑定到这些身份，不把旧 Core 结果冒充为 S1.0 证据。</p><h2 id="_6-2-产品级投影" tabindex="-1">6.2 产品级投影 <a class="header-anchor" href="#_6-2-产品级投影" aria-label="Permalink to &quot;6.2 产品级投影&quot;">​</a></h2><p>产品 Runner 导入精确 S1.0 Bundle，通过 CodeFlowMu Protocol Surface 验证 Lifecycle Profile，创建 CodeFlowMu <code>GovernanceReader</code>，并让 FCoP 派生的来源候选通过产品路径。Reference Reader Module 为可追踪性保留在 Bundle 中，但不被产品 Runner Import 或调用。</p><h2 id="_6-3-不削弱准则的回归对齐" tabindex="-1">6.3 不削弱准则的回归对齐 <a class="header-anchor" href="#_6-3-不削弱准则的回归对齐" aria-label="Permalink to &quot;6.3 不削弱准则的回归对齐&quot;">​</a></h2><p>保留的修复前 Runtime 运行记录为 1,520 passed、2 failed、1 skipped。失败来自仍预期 V1.7 文字的过期测试，以及“QA 执行完成”与“业务裁决失败”之间区分的过期预期。测试被调整到已经实现的契约；没有削弱任何 S1.0 Schema、Fixture、强制断言、Reader 行为或通过条件。</p><p>后续一次隔离的 Wake Endpoint 失败在五次即时重复中全部通过。一次 Full Run 还停滞于 <code>TaskDispatcher.test.ts</code>；精确子进程被终止，随后有界审计报告 29 passed / 0 failed。这些记录都保留在证据包中，没有被删除。</p><h1 id="_7-回归与复现器结果" tabindex="-1">7. 回归与复现器结果 <a class="header-anchor" href="#_7-回归与复现器结果" aria-label="Permalink to &quot;7. 回归与复现器结果&quot;">​</a></h1><table tabindex="0"><thead><tr><th>表面</th><th style="text-align:right;">最终结果</th><th>解释</th></tr></thead><tbody><tr><td>CodeFlowMu TMPA Runtime Suite</td><td style="text-align:right;">24 passed / 0 failed</td><td>产品 Reader 单元与集成表面</td></tr><tr><td>CodeFlowMu Runtime Full Suite</td><td style="text-align:right;">1,522 passed / 0 failed / 1 skipped</td><td>最终完整运行</td></tr><tr><td>Runtime 分批覆盖</td><td style="text-align:right;">207/207 Files；1,522 passed / 0 failed / 1 skipped</td><td>精确文件覆盖确认</td></tr><tr><td>CodeFlowMu Shell 分批覆盖</td><td style="text-align:right;">791 passed / 0 failed</td><td>精确八批执行</td></tr><tr><td>Protocol Validation 与 Typecheck</td><td style="text-align:right;">Exit 0</td><td>Schema 与 Validator 表面</td></tr><tr><td>FCoP 锁定参考实现</td><td style="text-align:right;">1,210 passed / 2 skipped</td><td>依赖回归；不替代产品 Reader</td></tr><tr><td>精简干净环境复现器</td><td style="text-align:right;">14/14 PASS</td><td><code>npm ci</code> 加精确 S1.0 产品 Runner</td></tr></tbody></table><p>复现器最初排除了整个 Protocol Schemas 目录，因此也误删所需 S1.0 Schema。这个缩减范围失败被保留。修正后的复现器只排除无关旧材料，保留 <code>schemas/tmpa</code>，从 Lock File 安装，并成功执行相同产品 Runner。</p><h1 id="_8-保留的-wp-13-证据门禁案例" tabindex="-1">8. 保留的 WP-13 证据门禁案例 <a class="header-anchor" href="#_8-保留的-wp-13-证据门禁案例" aria-label="Permalink to &quot;8. 保留的 WP-13 证据门禁案例&quot;">​</a></h1><p>WP-13 作为多 Agent 事实核查的现场案例保留，其中包含 Executor/Reviewer 分离、证据准入、审计记录与显式生命周期边界。证据包支持的有限结论是：在捕获的任务状态中，开发完成且角色分离 QA 通过。它同时记录后续任务快照仍是 <code>review</code> 与 <code>pending</code>，计划日期提前但没有找到单独改期批准文件，并且 Runtime Binding 与签名校验和位于证据边界之外。</p><p>WP-13 说明 TMPA 为什么区分执行证据、复核证据、授权、生命周期状态与出版声明。它不是 S1.0 C01–C14 产品 Fixture，不证明理论，不独立验证 CodeFlowMu，也不证明多 Agent 系统不会产生幻觉。</p><h1 id="_9-三值治理解释" tabindex="-1">9. 三值治理解释 <a class="header-anchor" href="#_9-三值治理解释" aria-label="Permalink to &quot;9. 三值治理解释&quot;">​</a></h1><p>TMPA 把语义裁决与视图分类分开：</p><table tabindex="0"><thead><tr><th>裁决</th><th>典型视图</th><th>含义</th></tr></thead><tbody><tr><td><code>valid</code></td><td>authoritative</td><td>所需证据与适用规则建立结论。</td></tr><tr><td><code>invalid</code></td><td>quarantined / rejected</td><td>确定性违规使相关证据或动作不能进入权威使用。</td></tr><tr><td><code>undetermined</code></td><td>partial / disputed / pending_human</td><td>证据缺失或冲突，或者仍需授权人工决定。</td></tr></tbody></table><p>V1.8.0 运行使这种分离可观察。类型错误、自我签发或其他未授权批准会被保留，但不能满足 C07。C09 中缺失引用使依赖主张保持 <code>undetermined</code>，而不是被静默标为完整。C12 中未授权 Resolution 仍是证据，但作为解决动作属于 <code>invalid</code>。C08 中完整性失败会隔离被覆盖内容，同时保留其来源记录。这些是针对证据的治理裁决，不是针对现实世界的语义真值裁决。</p><h1 id="_10-证据完整性与出版审计" tabindex="-1">10. 证据完整性与出版审计 <a class="header-anchor" href="#_10-证据完整性与出版审计" aria-label="Permalink to &quot;10. 证据完整性与出版审计&quot;">​</a></h1><p>正式归档包含 891 个 Entry、889 个文件。内部 SHA-256 Manifest 覆盖全部 889 个文件，外部 ZIP SHA-256 为 <code>9b92b06c3e46c8019362f55075be4ed066cb7a9c0d9859945b6c3b7de8840d04</code>。出版审计验证了：</p><ul><li>ZIP 路径安全与结构完整；</li><li>889/889 项内部 SHA-256；</li><li>884 个文本文件严格 UTF-8 解码；</li><li>全部 190 个 JSON 文件解析成功；</li><li>四份已发布 S1.0 Schema 与其余规范输入的字节一致性；</li><li>产品 Reader 被调用，Reference Reader 没有被替代调用；</li><li>C01–C14 结果 Envelope 符合 Schema；</li><li>十四个 Manifest Digest、十四个 Result Digest、71 项强制断言、聚合 Result Digest 与输入 Bundle Digest 的重新计算；</li><li>修复前失败、修复说明、原始命令、Exit Status、Dependency Lock、源码快照与 Patch 均被保留。</li></ul><p>重新计算没有发现任何 Digest 或断言差异。该审计建立提交包的内部一致性与可追踪性，不等于独立产品重跑或认证。</p><h1 id="_11-局限" tabindex="-1">11. 局限 <a class="header-anchor" href="#_11-局限" aria-label="Permalink to &quot;11. 局限&quot;">​</a></h1><ol><li>产品与回归证据由作者运行；没有独立组织认证或采用该实现。</li><li>CodeFlowMu 证据 Commit 在捕获时仅存在于本地，不是公开 Tag 或 Release；归档包含完整源码快照与 Patch 供检查。</li><li>证据 Worktree 为 tracked-clean，但原母体 Worktree 为 dirty 且持续变化；声明只绑定隔离证据 Worktree 与固定 Commit。</li><li>精简复现器演示符合性切片，不代表 CodeFlowMu 的每项私有部署依赖或全部运行环境。</li><li>Runtime 保留一项 Skip，FCoP 参考实现保留两项 Skip；这些 Skip 均不计为 C01–C14 产品结果。</li><li>C11 评估固定 Fixture 与声明的排列，不是对任意图、编码、文件系统或敌对平台的形式证明。</li><li>C08 演示治理对象完整性处理，不证明模型真实性、Actor 身份认证、安装器完整性或 Byzantine 韧性。</li><li>全套性能、代表性 SME 负担、比较基线、跨 Profile 可移植性与独立部署仍是开放的实证问题。</li><li>WP-13 是有限治理与证据准入案例，不是幻觉消除 Benchmark。</li></ol><h1 id="_12-声明账本" tabindex="-1">12. 声明账本 <a class="header-anchor" href="#_12-声明账本" aria-label="Permalink to &quot;12. 声明账本&quot;">​</a></h1><table tabindex="0"><thead><tr><th>声明</th><th>I1.0 处置</th></tr></thead><tbody><tr><td>TMPA Core S1.0 定义 C01–C14</td><td><strong>Specified</strong></td></tr><tr><td>CodeFlowMu V1.8.0 包含对应产品机制</td><td><strong>Implemented</strong></td></tr><tr><td>精确产品 Bundle 记录 14/14 PASS</td><td><strong>Demonstrated</strong></td></tr><tr><td>归档保留输入、源码、命令、输出、失败与 Hash</td><td><strong>Demonstrated</strong></td></tr><tr><td>精简符合性切片在捕获的干净复现器中成功运行</td><td><strong>Demonstrated</strong></td></tr><tr><td>CodeFlowMu 对任意输入与部署普遍符合</td><td><strong>未主张</strong></td></tr><tr><td>结果已经独立重跑、认证或采用</td><td><strong>未 Demonstrated</strong></td></tr><tr><td>实现证明 TMPA 理论</td><td><strong>禁止结论</strong></td></tr><tr><td>WP-13 证明幻觉消除</td><td><strong>禁止结论</strong></td></tr></tbody></table><h1 id="_13-工程结论" tabindex="-1">13. 工程结论 <a class="header-anchor" href="#_13-工程结论" aria-label="Permalink to &quot;13. 工程结论&quot;">​</a></h1><p>I1.0 为 TMPA Core S1.0 建立发布级精确输入工程基线。CodeFlowMu V1.8.0 通过自身产品 Adapter 与 Reader 路径满足全部十四项强制准则，记录 71 项强制断言，并保留检查结果所需的回归、修复、源码、依赖与完整性轨迹。S1.0 冻结候选基线与后续产品执行保持独立可识别。</p><p>该结果强化了 TMPA 可以指导具体工程系统的证据，但不会使 CodeFlowMu 成为定义 TMPA 的权威，也不会把工程成功转化为理论证明。依赖方向保持为：A1.0 陈述架构理论；S1.0 定义规范行为；FCoP 提供协作协议；CodeFlowMu 实现并消费治理投影；I1.0 报告有限证据。</p><h1 id="工件可用性" tabindex="-1">工件可用性 <a class="header-anchor" href="#工件可用性" aria-label="Permalink to &quot;工件可用性&quot;">​</a></h1><p>正式归档为 <a href="/joinwell52/evidence/tmpa/i1.0/tmpa-i1.0-codeflowmu-v1.8.0-s1.0-evidence-20260811.zip">tmpa-i1.0-codeflowmu-v1.8.0-s1.0-evidence-20260811.zip</a>。相邻文件 <code>tmpa-i1.0-codeflowmu-v1.8.0-s1.0-evidence-20260811.zip.sha256</code> 记录 <code>9b92b06c3e46c8019362f55075be4ed066cb7a9c0d9859945b6c3b7de8840d04</code>。</p><p>该运行已登记到 <a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/conformance/tmpa-core-s1.0/external-runs/20260811-codeflowmu-v1.8.0" target="_blank" rel="noreferrer">S1.0 外部运行注册表</a>。早期 I0.6–I0.8 证据包继续作为不可变历史保留在各自版本路径。Git History 是出版历史；没有平行论文数据库拥有编辑权威。</p><h1 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h1><p>[1] TMPA Project. “TMPA Core Specification S1.0,” frozen candidate commit <code>942cbb097eb3d662662f96a2269818ec9d7ca2ed</code>. GitHub, 2026.</p><p>[2] TMPA Project. “TMPA Architecture Paper A1.0.” GitHub, 2026.</p><p>[3] FCoP Project. “FCoP — File-based Coordination Protocol,” reference implementation commit <code>da79dfefd99f597c9e422ce9edec22157f915a21</code>. GitHub, 2026.</p><p>[4] CodeFlowMu Project. “CodeFlowMu V1.8.0 S1.0 Product Conformance,” evidence commit <code>c1e1f724293e8048fc3a956b6f6df8cf83f54830</code>, 2026.</p><p>[5] TMPA Project. “I1.0 CodeFlowMu V1.8.0 S1.0 Evidence,” package <code>tmpa-i1.0-codeflowmu-v1.8.0-s1.0-evidence-20260811</code>, 2026.</p><p>[6] CodeFlowMu Project. “WP-13 Multi-Agent Fact-Check Publication Evidence V3,” 2026.</p><p>[7] CodeFlowMu Project. “TMPA Governance: Theory-to-Engineering Relation,” <code>docs/TMPA-GOVERNANCE.md</code>. GitHub, 2026. <code>https://github.com/joinwell52-AI/codeflowmu/blob/main/docs/TMPA-GOVERNANCE.md</code>.</p>`,74))])}const f=d(l,[["render",s]]);export{m as __pageData,f as default};
